--
-- Name: find_category_id(text, text, public."CategoryType"); Type: FUNCTION; Schema: public; Owner: user
--

CREATE FUNCTION public.find_category_id(p_user_id text, p_category_name text, p_category_type public."CategoryType") RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_category_id INT;
BEGIN
    SELECT id INTO v_category_id FROM "Category" WHERE "userId" = p_user_id AND name = p_category_name;
    IF v_category_id IS NULL THEN
        INSERT INTO "Category" ("createdAt", "updatedAt", "userId", name, type) VALUES (CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, p_user_id, p_category_name, p_category_type) RETURNING id INTO v_category_id;
    END IF;
    RETURN v_category_id;
END;
$$;


